"""Импорт банковских выписок.

Поддерживаются три формата (определяются по заголовку):

    nova:        date,amount,description           (2026-03-01,-350.00,Кофейня)
    sfera:       Дата;Сумма;Описание               (01.03.2026;-350,00;Кофейня)
    sfera_split: Дата;Описание;Приход;Расход       (01.03.2026;Кофейня;;350,00)

Файл читается как UTF-8 (с BOM или без) либо cp1251.
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from collections.abc import Callable
from dataclasses import dataclass, replace
from decimal import Decimal
from pathlib import Path

from ledger.clock import Clock, SystemClock
from ledger.errors import StatementRowError, UnknownFormatError, ValidationError
from ledger.models import Transaction, parse_amount, to_money
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

_ISO_DATE = re.compile(r"\d{4}-\d{2}-\d{2}", re.ASCII)
_SFERA_DATE = re.compile(r"(\d{2})\.(\d{2})\.(\d{4})", re.ASCII)
# Без знака: тысячи через пробел или NBSP, запятая, не больше двух знаков после неё.
_SFERA_UNSIGNED_AMOUNT = re.compile(r"(\d{1,3}(?:[  ]\d{3})+|\d+)(,\d{1,2})?", re.ASCII)
_THOUSANDS_SEPARATORS = re.compile(r"[  ]")


@dataclass(frozen=True)
class RowError:
    """Строка выписки, которую не удалось разобрать.

    line_no — физическая строка, с которой начинается запись (заголовок — строка 1).
    """

    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    """Итог импорта.

    added + duplicates + len(errors) равно числу непустых строк данных в файле.
    """

    format: str
    encoding: str
    added: int
    duplicates: int
    errors: tuple[RowError, ...]


@dataclass(frozen=True)
class _Format:
    name: str
    delimiter: str
    # Имена обязательных колонок в виде strip().casefold().
    columns: tuple[str, ...]
    # Из значений колонок (ключи — из columns) получает дату, сумму и описание.
    parse: Callable[[dict[str, str]], tuple[dt.date, Decimal, str]]


@dataclass(frozen=True)
class _Header:
    format: _Format
    # Колонка из format.columns -> её индекс в строке.
    index: dict[str, int]
    # Число колонок в заголовке; лишние непустые ячейки сверх него — ошибка строки.
    width: int


def normalize_description(text: str) -> str:
    """Вид описания для сравнения; совпадает с правилами категоризации проекта."""
    return normalize_text(text)


def _parse_iso_date(text: str) -> dt.date:
    if not _ISO_DATE.fullmatch(text.strip()):
        raise ValidationError(f"invalid date {text!r}")
    try:
        return dt.date.fromisoformat(text.strip())
    except ValueError as exc:
        raise ValidationError(f"invalid date {text!r}") from exc


def _parse_sfera_date(text: str) -> dt.date:
    match = _SFERA_DATE.fullmatch(text.strip())
    if match is None:
        raise ValidationError(f"invalid date {text!r}, expected DD.MM.YYYY")
    day, month, year = (int(part) for part in match.groups())
    try:
        return dt.date(year, month, day)
    except ValueError as exc:
        raise ValidationError(f"invalid date {text!r}") from exc


def _parse_sfera_amount(text: str, *, signed: bool) -> Decimal:
    body = text.strip()
    sign = ""
    if body.startswith(("+", "-")):
        if not signed:
            raise ValidationError(f"sign is not allowed in this column: {text!r}")
        sign, body = body[0], body[1:]
    if not _SFERA_UNSIGNED_AMOUNT.fullmatch(body):
        raise ValidationError(f"invalid amount: {text!r}")
    normalized = _THOUSANDS_SEPARATORS.sub("", body).replace(",", ".")
    return to_money(Decimal(sign + normalized))


def _parse_nova(values: dict[str, str]) -> tuple[dt.date, Decimal, str]:
    return (
        _parse_iso_date(values["date"]),
        parse_amount(values["amount"]),
        values["description"].strip(),
    )


def _parse_sfera(values: dict[str, str]) -> tuple[dt.date, Decimal, str]:
    return (
        _parse_sfera_date(values["дата"]),
        _parse_sfera_amount(values["сумма"], signed=True),
        values["описание"].strip(),
    )


def _parse_split_column(text: str) -> Decimal | None:
    """Сумма колонки прихода или расхода; None — колонка пуста или равна нулю."""
    if not text.strip():
        return None
    amount = _parse_sfera_amount(text, signed=False)
    return None if amount == 0 else amount


